import { apiClient, unwrap, type BffResponse } from './api';
import type { CatalogUiSchema, SaveCatalogUiSchema } from '@linm-soft-org/linm-web-common-components';

const base = (catalogKind: string) =>
  `/master/catalogs/${encodeURIComponent(catalogKind)}/ui-schema`;

export const catalogUiSchemaService = {
  get: async (catalogKind: string, configMode = false): Promise<CatalogUiSchema> => {
    const qs = configMode ? '?configMode=true' : '';
    const res = await apiClient.get<BffResponse<CatalogUiSchema>>(`${base(catalogKind)}${qs}`);
    return unwrap(res)!;
  },

  save: async (catalogKind: string, body: SaveCatalogUiSchema): Promise<CatalogUiSchema> => {
    const res = await apiClient.put<BffResponse<CatalogUiSchema>>(base(catalogKind), body);
    return unwrap(res)!;
  },
};

export function resolveApiErrorMessage(err: unknown, fallback: string): string {
  if (err && typeof err === 'object') {
    const anyErr = err as { message?: string; response?: { data?: { message?: string } } };
    const fromBody = anyErr.response?.data?.message;
    if (fromBody) return fromBody;
    if (anyErr.message) return anyErr.message;
  }
  if (err instanceof Error && err.message) return err.message;
  return fallback;
}
