import { createDocumentHistoryClient } from '@linm-soft-org/linm-web-common-components';

/** ERP WebService — document history API. */
export const erpDocumentHistoryClient = createDocumentHistoryClient({
  basePath: '/document-history',
  pageSize: 20,
});

/** FPC PriorityClass — matches BE `FpcDocumentTypes.PriorityClass`. */
export const FPC_PRIORITY_CLASS_DOCUMENT_TYPE = 'FpcPriorityClass';
export const FPC_SENSITIVITY_VARIABLE_DOCUMENT_TYPE = 'FpcSensitivityVariable';

/** Catalog UI schema kind — matches BE `CatalogUiSchemaRegistry.PriorityClasses`. */
export const FPC_PRIORITY_CLASS_CATALOG_KIND = 'priority-classes';
export const FPC_SENSITIVITY_VARIABLE_CATALOG_KIND = 'sensitivity-variables';
